<?php require_once __DIR__.'/../includes/functions.php';need_role(['petugas']);$s=db()->prepare('SELECT * FROM users WHERE id_user=?');$s->execute([me()['id_user']]);$u=$s->fetch();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['nama_lengkap']??'');$phone=trim($_POST['no_hp']??'');$addr=trim($_POST['alamat']??'');$pw=$_POST['password_baru']??'';if($name==='')$err='Nama lengkap wajib diisi.';elseif($pw!==''&&strlen($pw)<8)$err='Kata sandi minimal 8 karakter.';else{if($pw!=='')db()->prepare('UPDATE users SET nama_lengkap=?,no_hp=?,alamat=?,password=?,updated_at=NOW() WHERE id_user=?')->execute([$name,$phone,$addr,password_hash($pw,PASSWORD_DEFAULT),me()['id_user']]);else db()->prepare('UPDATE users SET nama_lengkap=?,no_hp=?,alamat=?,updated_at=NOW() WHERE id_user=?')->execute([$name,$phone,$addr,me()['id_user']]);$_SESSION['user']['nama_lengkap']=$name;log_activity('ubah_profil','Profil pengguna diperbarui');flash('success','Profil diperbarui.');go('profil.php');}}header_page('Profil petugas');?><section class="card"><h1>Profil petugas</h1><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><?=csrf_input()?><label>Nama lengkap<input name="nama_lengkap" maxlength="120" value="<?=e($u['nama_lengkap'])?>" required></label><label>Email<input value="<?=e($u['email'])?>" disabled></label><label>Nomor HP<input name="no_hp" maxlength="30" value="<?=e($u['no_hp'])?>"></label><label>Alamat<textarea name="alamat"><?=e($u['alamat'])?></textarea></label><label>Kata sandi baru (kosongkan jika tidak diganti)<input type="password" name="password_baru" minlength="8" autocomplete="new-password"></label><button class="btn">Simpan perubahan</button></form></section><?php footer_page();?>